<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Citas y asistencia</title><style>@page{size:A4;margin:14mm}body{font-family:Arial,sans-serif;color:#172b4d;font-size:10px}h1{margin:0 0 4px;font-size:20px}.muted{color:#64748b}.summary{display:flex;gap:18px;margin:14px 0;padding:10px;background:#f1f5f9}.summary strong{display:block;font-size:15px}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #dbe3ec;padding:6px 4px;text-align:left;vertical-align:top}th{font-size:9px;text-transform:uppercase;color:#64748b}.filters{margin-top:8px}@media print{.no-print{display:none}}</style></head><body><h1>Citas y asistencia</h1><div class="muted">Generado el {{ now('America/Lima')->format('d/m/Y H:i') }} · Fechas: {{ $filters['from']->format('d/m/Y') }} al {{ $filters['to']->format('d/m/Y') }}</div><div class="summary"><div><span>Total de citas</span><strong>{{ $summary['total'] }}</strong></div>@foreach($summary['states'] as $state=>$count)<div><span>{{ str_replace('_',' ', $state) }}</span><strong>{{ $count }}</strong></div>@endforeach</div><table><thead><tr><th>Fecha</th><th>Hora</th><th>Paciente / documento</th><th>Odontólogo</th><th>Consultorio</th><th>Motivo</th><th>Estado cita</th><th>Estado atención</th></tr></thead><tbody>@forelse($allAppointments as $appointment)<tr><td>{{ optional($appointment->fecha)->format('d/m/Y') }}</td><td>{{ $appointment->hora_inicio }}</td><td>{{ trim(($appointment->paciente?->nombres ?? '').' '.($appointment->paciente?->apellidos ?? '')) }}<br>{{ $appointment->paciente?->numero_documento }}</td><td>{{ $appointment->odontologo?->nombre_completo ?: '—' }}</td><td>{{ $appointment->consultorio?->nombre ?: '—' }}</td><td>{{ $appointment->motivo ?: '—' }}</td><td>{{ str_replace('_',' ', $appointment->estado) }}</td><td>{{ $appointment->atencion?->estado ?: 'Sin atención' }}</td></tr>@empty<tr><td colspan="8">No hay citas para los filtros seleccionados.</td></tr>@endforelse</tbody></table></body></html>
